export const stationSlotTrans = (function () {
    const o1 = 1.256, o2 = 2.7;
    const slots = [
        [ o1,  o2], [  0,  o2], [-o1,  o2],
        [-o2,  o1], [-o2,   0], [-o2, -o1],
        [-o1, -o2], [  0, -o2], [ o1, -o2],
        [ o2, -o1], [ o2,   0], [ o2,  o1],
    ] as const;
    return slots.map(s => new Matrix4().makeTranslation(s[0], s[1], 0.));
})();
